SELECT COUNT(*)
FROM mk_suppression
WHERE tenant_id = #{tenantId}
  AND subject_token = #{subjectToken}
  AND (channel_name = #{channelName} OR channel_name = '*')
  AND (expires_at IS NULL OR expires_at > #{now})

