SELECT contact_count
FROM mk_frequency_bucket
WHERE tenant_id = #{tenantId}
  AND campaign_id = #{campaignId}
  AND channel_name = #{channelName}
  AND subject_token = #{subjectToken}
  AND window_bucket = #{windowBucket}
FOR UPDATE

mapper.insert:
INSERT INTO mk_frequency_bucket (
    tenant_id, campaign_id, channel_name, subject_token, window_bucket, contact_count, updated_at
) VALUES (
    #{tenantId}, #{campaignId}, #{channelName}, #{subjectToken}, #{windowBucket}, 1, #{updatedAt}
)

mapper.update:
UPDATE mk_frequency_bucket
SET contact_count = contact_count + 1,
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}
  AND campaign_id = #{campaignId}
  AND channel_name = #{channelName}
  AND subject_token = #{subjectToken}
  AND window_bucket = #{windowBucket}

